using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city.")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);

        if (response?.CurrentCondition is not [var current, ..])
            return $"No weather data found for '{city}'.";

        return $"""
            Weather for {city}:
              Temperature: {current.TempC}°C / {current.TempF}°F
              Condition:   {current.Description}
              Humidity:    {current.Humidity}%
              Wind:        {current.WindspeedKmph} km/h {current.WindDir}
            """;
    }

    [McpServerTool, Description("Get a short weather forecast summary for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);

        if (response?.Weather is null || response.Weather.Count == 0)
            return $"No forecast data found for '{city}'.";

        var lines = response.Weather.Take(days).Select(d =>
            $"  {d.Date}: {d.MinTempC}-{d.MaxTempC}°C");

        return $"Forecast for {city}:\n{string.Join('\n', lines)}";
    }
}

// DTOs for the wttr.in JSON API
public sealed class WeatherResponse
{
    [JsonPropertyName("current_condition")]
    public List<CurrentCondition>? CurrentCondition { get; set; }

    [JsonPropertyName("weather")]
    public List<DayForecast>? Weather { get; set; }
}

public sealed class CurrentCondition
{
    [JsonPropertyName("temp_C")]
    public string? TempC { get; set; }

    [JsonPropertyName("temp_F")]
    public string? TempF { get; set; }

    [JsonPropertyName("weatherDesc")]
    public List<WeatherDesc>? WeatherDesc { get; set; }

    [JsonPropertyName("humidity")]
    public string? Humidity { get; set; }

    [JsonPropertyName("windspeedKmph")]
    public string? WindspeedKmph { get; set; }

    [JsonPropertyName("winddir16Point")]
    public string? WindDir { get; set; }

    public string Description => WeatherDesc?.FirstOrDefault()?.Value ?? "Unknown";
}

public sealed class WeatherDesc
{
    [JsonPropertyName("value")]
    public string? Value { get; set; }
}

public sealed class DayForecast
{
    [JsonPropertyName("date")]
    public string? Date { get; set; }

    [JsonPropertyName("mintempC")]
    public string? MinTempC { get; set; }

    [JsonPropertyName("maxtempC")]
    public string? MaxTempC { get; set; }
}

